INSERT INTO public.questions (id,exam,domain_id,stem,difficulty,source_ref,status,review_status) VALUES ('456f1207-aaf3-5fdb-9294-2090db4885c9','GCP_PM_ML_ENG',(SELECT id FROM public.exam_domains WHERE code='AUTOMATING_AND_ORCHESTRATING_ML_PIPELINES'),'A pipeline should deploy a candidate only when its evaluation meets a threshold. How should this be implemented?','MEDIUM','local-educational-seed-22','ACTIVE','GOOD') ON CONFLICT DO NOTHING;
