INSERT INTO public.answers (id,question_id,choice_label,choice_text,is_correct,explanation_text) VALUES ('ec7339b8-cc4d-5280-9d4c-ed240fa15a72','456f1207-aaf3-5fdb-9294-2090db4885c9','D','Remove the evaluation component',false,'Removing evaluation eliminates evidence for the deployment decision.') ON CONFLICT DO NOTHING;
