INSERT INTO public.questions (id,exam,domain_id,stem,difficulty,source_ref,status,review_status) VALUES ('64db2b81-8ad6-5cb5-b8ab-d4355898cfa1','GCP_PM_ML_ENG',(SELECT id FROM public.exam_domains WHERE code='AUTOMATING_AND_ORCHESTRATING_ML_PIPELINES'),'A preprocessing pipeline step is unchanged and has the same versioned inputs as a previous run. How can duplicate work be reduced?','MEDIUM','local-educational-seed-23','ACTIVE','GOOD') ON CONFLICT DO NOTHING;
INSERT INTO public.answers (id,question_id,choice_label,choice_text,is_correct,explanation_text) VALUES ('0088cb8b-5331-5e3b-bf3b-a16f8076436a','64db2b81-8ad6-5cb5-b8ab-d4355898cfa1','A','Use pipeline caching where the component and inputs are deterministic',true,'Caching can reuse prior outputs when the inputs and computation identity match.') ON CONFLICT DO NOTHING;
