INSERT INTO public.questions (id,exam,domain_id,stem,difficulty,source_ref,status,review_status) VALUES ('a98a6be6-565a-57e5-bec1-85f5ff64b237','GCP_PM_ML_ENG',(SELECT id FROM public.exam_domains WHERE code='AUTOMATING_AND_ORCHESTRATING_ML_PIPELINES'),'A pipeline step accesses storage with more permissions than it needs. What is the recommended control?','MEDIUM','local-educational-seed-24','ACTIVE','GOOD') ON CONFLICT DO NOTHING;
