INSERT INTO public.questions (id,exam,domain_id,stem,difficulty,source_ref,status,review_status) VALUES ('218414fd-31f4-5881-b3aa-e00e608b4e62','GCP_PM_ML_ENG',(SELECT id FROM public.exam_domains WHERE code='AUTOMATING_AND_ORCHESTRATING_ML_PIPELINES'),'A scheduled retraining job fails after partially writing outputs. What design improves safe retries?','MEDIUM','local-educational-seed-25','ACTIVE','GOOD') ON CONFLICT DO NOTHING;
