INSERT INTO public.questions (id,exam,domain_id,stem,difficulty,source_ref,status,review_status) VALUES ('ac463e75-927a-5955-bfe0-0353c1d70c94','GCP_PM_ML_ENG',(SELECT id FROM public.exam_domains WHERE code='MONITORING_ML_SOLUTIONS'),'Production feature distributions have shifted from the training data. Which monitoring signal identifies this?','MEDIUM','local-educational-seed-26','ACTIVE','GOOD') ON CONFLICT DO NOTHING;
