INSERT INTO public.answers (id,question_id,choice_label,choice_text,is_correct,explanation_text) VALUES ('602fdcc9-65d1-56e1-b5b5-67f8f9c709fb','9bb42ee3-7d6a-5bb9-8b86-cf01ac59b3bc','A','Track input and prediction signals promptly, then join delayed labels for performance evaluation',true,'Operational signals provide early warning while delayed labels support actual quality metrics.') ON CONFLICT DO NOTHING;
