INSERT INTO public.questions (id,exam,domain_id,stem,difficulty,source_ref,status,review_status) VALUES ('3c2383ed-a6c0-5d7f-b0c2-cc59eb43ac66','GCP_PM_ML_ENG',(SELECT id FROM public.exam_domains WHERE code='MONITORING_ML_SOLUTIONS'),'An endpoint has increased tail latency while average latency looks stable. Which metric should be examined?','MEDIUM','local-educational-seed-28','ACTIVE','GOOD') ON CONFLICT DO NOTHING;
INSERT INTO public.answers (id,question_id,choice_label,choice_text,is_correct,explanation_text) VALUES ('f9abad4f-63ab-549f-8a83-21828f24f521','3c2383ed-a6c0-5d7f-b0c2-cc59eb43ac66','A','High-percentile latency such as p95 or p99 together with error rates',true,'Tail percentiles expose slow requests hidden by averages.') ON CONFLICT DO NOTHING;
