INSERT INTO public.questions (id,exam,domain_id,stem,difficulty,source_ref,status,review_status) VALUES ('d83b827b-6bd3-5261-8824-ca7e1ca72359','GCP_PM_ML_ENG',(SELECT id FROM public.exam_domains WHERE code='MONITORING_ML_SOLUTIONS'),'A classifier has good overall performance but poor recall for an important customer group. What should be done?','MEDIUM','local-educational-seed-29','ACTIVE','GOOD') ON CONFLICT DO NOTHING;
INSERT INTO public.answers (id,question_id,choice_label,choice_text,is_correct,explanation_text) VALUES ('ad6d41e6-1489-52e1-a737-d445047664ef','d83b827b-6bd3-5261-8824-ca7e1ca72359','A','Evaluate metrics by relevant slices and investigate data coverage and thresholds',true,'Slice evaluation exposes uneven performance concealed by aggregate metrics.') ON CONFLICT DO NOTHING;
