INSERT INTO public.answers (id,question_id,choice_label,choice_text,is_correct,explanation_text) VALUES ('ae1b11e8-eeba-540a-862e-5c0b85141e5e','b6a36901-6237-524c-8b0f-4106fbcfbfc5','A','Calibrate thresholds and alert windows using meaningful changes and operational response needs',true,'Actionable thresholds reduce noise while retaining useful detection.') ON CONFLICT DO NOTHING;
